var paths=new[]{"Assets/Prefabs/Weapons/Enemy_Entity.prefab","Assets/Prefabs/Bosses/SH10_L01_BossGameplay.prefab"};var changed=0;foreach(var path in paths){var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);try{var visual=root.transform.Cast<UnityEngine.Transform>().FirstOrDefault(t=>t.name=="SH10_Visual");if(visual==null)throw new System.Exception("SH10_Visual missing: "+path);visual.localRotation=UnityEngine.Quaternion.Euler(0f,180f,0f);UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,path);changed++;}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}}UnityEditor.AssetDatabase.SaveAssets();return new{prefabsChanged=changed,rotation="Y 180 degrees"};
